files.content:
* {
  box-sizing: border-box;
}

.body {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  min-width: 850px;
  margin: 0 auto;
  padding-bottom: 20px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

h2 {
  max-width: 950px;
  margin: 0 0 20px;
  border: 1px solid #000;
  padding: 20px 0;
  font-weight: 800;
  font-size: 38px;
  text-align: center;
  text-transform: uppercase;
}

h3 {
  align-self: flex-start;
  font-weight: 400;
  font-size: 16px;
}

.container {
  display: grid;
  grid-template-columns: repeat(auto-fit, 300px);
  gap: 20px;
  width: 100%;
}

.block {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  border: 1px solid black;
  padding: 20px;
  background-color: white;
}

img {
  width: 200px;
  border: 1px solid #000;
}

.block--1 {
  background-color: #c4c4c4;
}

.block--2 {
  background-color: #feafe8;
}

.block--3 {
  background-color: #80d994;
}

.block__button {
  width: 100%;
  border: 1px solid #000;
  padding: 20px 0;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

button:focus-visible {
  outline: 2px solid #000;
  outline-offset: 0;
}
